initial_condition:
with {
   the SUT containing an initial state
}

test_cases.then:
then {
    the SUT sends a valid Response for the operations:
        Create Subscription with Response Status Code set to 400     and
        Create Subscription with Response Body containing the type 'https://uri.etsi.org/ngsi-ld/errors/BadRequestData'     and
        Create Subscription with Response body containing 'title' element
}

then {
    the SUT sends a valid Response for the operations:
        Create Subscription with Response Status Code set to 503     and
        Create Subscription with Response Body containing the type 'https://uri.etsi.org/ngsi-ld/errors/LdContextNotAvailable'     and
        Create Subscription with Response body containing 'title' element
}
